let entities: Map<string, number> | undefined;

export const namedEntity = (name: string) => {
	if (!entities) {
		entities = new Map();
		for (const [value, names] of groups) {
			for (const entry of names.split(' ')) {
				entities.set(entry, value);
			}
		}
	}
	return entities.get(name);
};
